-- Colonias de San Bernabé y vecinas con su índice y grado de marginación urbana 2020 (CONAPO).
-- Fuente: https://www.gob.mx/conapo/documentos/indices-de-marginacion-2020-284372

CREATE TABLE IF NOT EXISTS colonia_marginacion (
    cve_col        varchar(20)  PRIMARY KEY,
    colonia        varchar(160) NOT NULL,
    codigo_postal  char(5),
    municipio      varchar(80)  NOT NULL,
    poblacion      integer      NOT NULL CHECK (poblacion >= 0),
    indice_2020    numeric(10,4),
    grado_2020     varchar(12)  NOT NULL
                   CHECK (grado_2020 IN ('Muy bajo','Bajo','Medio','Alto','Muy alto')),
    sin_educacion_basica_pct numeric(6,2), sin_salud_pct numeric(6,2), hacinamiento_pct numeric(6,2), sin_internet_pct numeric(6,2),
    latitud        numeric(9,6) NOT NULL,
    longitud       numeric(9,6) NOT NULL,
    contorno       jsonb        NOT NULL
);
COMMENT ON TABLE colonia_marginacion IS 'Colonias de la zona de estudio con el índice de marginación urbana 2020 de CONAPO. Bajos ingresos = grado Medio, Alto o Muy alto.';

ON CONFLICT (cve_col) DO NOTHING;
